(function(api){
var sands=[];
function num(k,d){ var p=api.params||{}; return p[k]!=null?+p[k]:d; }
function frame(dt){
  var W=api.width,H=api.height; if(!W||!H) return;
  var f=dt/16.6;
  var ctx=api.ctx;
  ctx.clearRect(0,0,W,H);
  var amt=num('sand',5), wind=num('wind',7), vis=num('visibility',3);
  if(amt>0){
    var n=Math.floor(amt*16);
    while(sands.length<n){ sands.push({x:api.rand(-80,W), y:api.rand(0,H), l:api.rand(8,26), v:api.rand(6,14)}); }
    if(sands.length>n+40) sands.length=n+40;
    ctx.strokeStyle='rgba(215,212,205,0.5)';
    ctx.lineWidth=1;
    ctx.beginPath();
    for(var i=0;i<sands.length;i++){
      var s=sands[i];
      s.x+=s.v*f*(0.5+wind*0.18);
      s.y+=api.rand(-0.4,0.4)*f;
      if(s.x-s.l>W+40){ s.x=api.rand(-60,-10); s.y=api.rand(0,H); }
      if(s.y<0)s.y=H; if(s.y>H)s.y=0;
      ctx.moveTo(s.x-s.l,s.y);
      ctx.lineTo(s.x,s.y);
    }
    ctx.stroke();
  }
  if(vis>0){
    ctx.fillStyle='rgba(190,188,180,'+(0.025*vis)+')';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='rgba(0,0,0,'+(0.02*vis)+')';
    ctx.fillRect(0,0,W,H);
  }
}
function clear(){ try{ api.ctx.clearRect(0,0,api.width,api.height); }catch(e){} sands=[]; }
return { frame:frame, clear:clear, resize:clear };
})
